import React, { useState } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import productsData from '../data/productsData';
import AuthModal from '../components/AuthModal';
import './ProductDetails.css';

const ProductDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [isFavorite, setIsFavorite] = useState(false);
  const [showAuth, setShowAuth] = useState(false);
  const [currentUser, setCurrentUser] = useState(() => {
    const saved = localStorage.getItem('campusUser');
    return saved ? JSON.parse(saved) : null;
  });
  const [buySuccess, setBuySuccess] = useState(false);

  // Find product by ID
  const product = productsData.find((p) => p.id === parseInt(id));

  // Get related products from same category (3 random products)
  const relatedProducts = product
    ? productsData
        .filter((p) => p.category === product.category && p.id !== product.id)
        .slice(0, 3)
    : [];

  // ✅ ALL HANDLERS BEFORE if(!product) CHECK
  const handleBuy = () => {
    if (currentUser) {
      setBuySuccess(true);
      setTimeout(() => setBuySuccess(false), 3000);
    } else {
      setShowAuth(true);
    }
  };

  const handleAuthSuccess = (user) => {
    setCurrentUser(user);
    setBuySuccess(true);
    setTimeout(() => setBuySuccess(false), 3000);
  };

  const handleLogout = () => {
    localStorage.removeItem('campusUser');
    setCurrentUser(null);
  };

  if (!product) {
    return (
      <main className="page-shell">
        <section className="not-found" style={{ textAlign: 'center', padding: '60px 20px' }}>
          <h2>Product not found</h2>
          <p>Sorry, we couldn't find the product you're looking for.</p>
          <button
            onClick={() => navigate('/')}
            className="gradient-btn"
            style={{ marginTop: '20px' }}
          >
            ← Back to Browse
          </button>
        </section>
      </main>
    );
  }

  return (
    <main className="page-shell product-details-page">

      {/* AUTH MODAL */}
      <AuthModal
        isOpen={showAuth}
        onClose={() => setShowAuth(false)}
        onSuccess={handleAuthSuccess}
      />

      {/* Back Button */}
      <button
        type="button"
        className="back-button"
        onClick={() => navigate(-1)}
        style={{
          background: 'rgba(15, 23, 42, 0.08)',
          border: 'none',
          padding: '10px 16px',
          borderRadius: '8px',
          cursor: 'pointer',
          fontSize: '14px',
          fontWeight: '600',
          color: '#0f172a',
          marginBottom: '24px',
          transition: 'all 0.3s ease',
          display: 'inline-flex',
          alignItems: 'center',
          gap: '8px'
        }}
        onMouseEnter={(e) => (e.currentTarget.style.background = 'rgba(15, 23, 42, 0.15)')}
        onMouseLeave={(e) => (e.currentTarget.style.background = 'rgba(15, 23, 42, 0.08)')}
      >
        ← Back
      </button>

      {/* Product Main Section */}
      <section className="product-details-container">
        {/* Image Section */}
        <div className="product-image-section">
          <div
            className="product-main-image"
            style={{
              backgroundImage: `url(${product.image || product.img || product.photo || "https://via.placeholder.com/500"})`,
              backgroundSize: 'cover',
              backgroundPosition: 'center',
              width: '100%',
              maxWidth: '500px',
              height: '500px',
              borderRadius: '16px',
              boxShadow: '0 20px 60px rgba(15, 23, 42, 0.15)',
              position: 'relative',
              overflow: 'hidden'
            }}
          >
            {/* Favorite Button */}
            <button
              type="button"
              onClick={() => setIsFavorite(!isFavorite)}
              style={{
                position: 'absolute',
                top: '16px',
                right: '16px',
                width: '48px',
                height: '48px',
                borderRadius: '50%',
                border: 'none',
                background: isFavorite ? 'linear-gradient(135deg, #ec4899, #f43f5e)' : 'rgba(255, 255, 255, 0.95)',
                fontSize: '24px',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                transition: 'all 0.3s ease',
                boxShadow: '0 4px 12px rgba(0, 0, 0, 0.15)'
              }}
              title={isFavorite ? 'Remove from favorites' : 'Add to favorites'}
            >
              {isFavorite ? '❤️' : '🤍'}
            </button>

            {/* Badge */}
            <span
              style={{
                position: 'absolute',
                top: '16px',
                left: '16px',
                background: 'linear-gradient(135deg, #ec4899, #f43f5e)',
                color: 'white',
                padding: '8px 16px',
                borderRadius: '20px',
                fontSize: '12px',
                fontWeight: '700',
                textTransform: 'uppercase',
                letterSpacing: '0.5px',
                boxShadow: '0 4px 12px rgba(236, 72, 153, 0.3)'
              }}
            >
              {product.category}
            </span>
          </div>
        </div>

        {/* Details Section */}
        <div className="product-details-info">
          {/* Title and Price */}
          <div style={{ marginBottom: '24px' }}>
            <h1
              style={{
                fontSize: '32px',
                fontWeight: '800',
                color: '#0f172a',
                marginBottom: '12px',
                lineHeight: '1.2'
              }}
            >
              {product?.title || "No Title"}
            </h1>
            <p style={{ fontSize: '14px', color: '#64748b', marginBottom: '16px' }}>
              Posted {product.postedDate} • Condition: {product.condition}
            </p>
            <div
              style={{
                fontSize: '40px',
                fontWeight: '900',
                background: 'linear-gradient(135deg, #ec4899, #f43f5e)',
                backgroundClip: 'text',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent',
                color: '#ec4899'
              }}
            >
              ${product?.price || "0"}
            </div>
          </div>

          {/* Description */}
          <div
            style={{
              background: 'rgba(15, 23, 42, 0.04)',
              padding: '20px',
              borderRadius: '12px',
              marginBottom: '24px',
              borderLeft: '4px solid #ec4899'
            }}
          >
            <h3 style={{ fontSize: '14px', fontWeight: '600', color: '#64748b', marginBottom: '8px' }}>
              Description
            </h3>
            <p style={{ fontSize: '15px', color: '#334155', lineHeight: '1.6' }}>
              {product?.description || "No description available"}
            </p>
          </div>

          {/* Product Specifications */}
          <div style={{ marginBottom: '24px' }}>
            <h3 style={{ fontSize: '16px', fontWeight: '700', color: '#0f172a', marginBottom: '16px' }}>
              Product Details
            </h3>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '12px' }}>
              {product.pages && (
                <div style={{ background: '#f1f5f9', padding: '12px', borderRadius: '8px' }}>
                  <p style={{ fontSize: '12px', color: '#64748b', marginBottom: '4px' }}>Pages</p>
                  <p style={{ fontSize: '14px', fontWeight: '600', color: '#0f172a' }}>{product.pages}</p>
                </div>
              )}
              {product.author && (
                <div style={{ background: '#f1f5f9', padding: '12px', borderRadius: '8px' }}>
                  <p style={{ fontSize: '12px', color: '#64748b', marginBottom: '4px' }}>Author</p>
                  <p style={{ fontSize: '14px', fontWeight: '600', color: '#0f172a' }}>{product.author}</p>
                </div>
              )}
              {product.processor && (
                <div style={{ background: '#f1f5f9', padding: '12px', borderRadius: '8px' }}>
                  <p style={{ fontSize: '12px', color: '#64748b', marginBottom: '4px' }}>Processor</p>
                  <p style={{ fontSize: '14px', fontWeight: '600', color: '#0f172a' }}>{product.processor}</p>
                </div>
              )}
              {product.ram && (
                <div style={{ background: '#f1f5f9', padding: '12px', borderRadius: '8px' }}>
                  <p style={{ fontSize: '12px', color: '#64748b', marginBottom: '4px' }}>RAM</p>
                  <p style={{ fontSize: '14px', fontWeight: '600', color: '#0f172a' }}>{product.ram}</p>
                </div>
              )}
              {product.storage && (
                <div style={{ background: '#f1f5f9', padding: '12px', borderRadius: '8px' }}>
                  <p style={{ fontSize: '12px', color: '#64748b', marginBottom: '4px' }}>Storage</p>
                  <p style={{ fontSize: '14px', fontWeight: '600', color: '#0f172a' }}>{product.storage}</p>
                </div>
              )}
              {product.battery && (
                <div style={{ background: '#f1f5f9', padding: '12px', borderRadius: '8px' }}>
                  <p style={{ fontSize: '12px', color: '#64748b', marginBottom: '4px' }}>Battery</p>
                  <p style={{ fontSize: '14px', fontWeight: '600', color: '#0f172a' }}>{product.battery}</p>
                </div>
              )}
              {product.brand && (
                <div style={{ background: '#f1f5f9', padding: '12px', borderRadius: '8px' }}>
                  <p style={{ fontSize: '12px', color: '#64748b', marginBottom: '4px' }}>Brand</p>
                  <p style={{ fontSize: '14px', fontWeight: '600', color: '#0f172a' }}>{product.brand}</p>
                </div>
              )}
              {product.warranty && (
                <div style={{ background: '#f1f5f9', padding: '12px', borderRadius: '8px' }}>
                  <p style={{ fontSize: '12px', color: '#64748b', marginBottom: '4px' }}>Warranty</p>
                  <p style={{ fontSize: '14px', fontWeight: '600', color: '#0f172a' }}>{product.warranty}</p>
                </div>
              )}
            </div>
          </div>

          {/* Seller Card */}
          <div
            style={{
              background: 'linear-gradient(135deg, #f8f4ff 0%, #fdf2f8 100%)',
              padding: '24px',
              borderRadius: '12px',
              border: '2px solid #ec4899',
              marginBottom: '24px'
            }}
          >
            <h3 style={{ fontSize: '16px', fontWeight: '700', color: '#0f172a', marginBottom: '16px' }}>
              Seller Information
            </h3>

            <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '16px' }}>
              <div
                style={{
                  width: '56px',
                  height: '56px',
                  borderRadius: '50%',
                  background: 'linear-gradient(135deg, #ec4899, #f43f5e)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontSize: '28px'
                }}
              >
                {product?.name?.charAt(0) || "U"}
              </div>
              <div>
                <p style={{ fontSize: '16px', fontWeight: '700', color: '#0f172a', marginBottom: '4px' }}>
                  {product.name}
                </p>
                <p style={{ fontSize: '13px', color: '#64748b' }}>📍 {product.location}</p>
              </div>
            </div>

            <div style={{ display: 'grid', gap: '12px', marginBottom: '16px' }}>
              <a
                href={`tel:${product.contact}`}
                style={{
                  display: 'flex', alignItems: 'center', gap: '8px',
                  fontSize: '14px', color: '#ec4899', textDecoration: 'none', fontWeight: '600'
                }}
              >
                📞 {product.contact}
              </a>
              {product.email && (
                <a
                  href={`mailto:${product.email}`}
                  style={{
                    display: 'flex', alignItems: 'center', gap: '8px',
                    fontSize: '14px', color: '#0f172a', textDecoration: 'none', fontWeight: '600'
                  }}
                >
                  ✉️ {product.email}
                </a>
              )}
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
              <a
                href={`tel:${product.contact}`}
                style={{
                  background: 'linear-gradient(135deg, #ec4899, #f43f5e)',
                  color: 'white', border: 'none', padding: '12px 20px',
                  borderRadius: '8px', cursor: 'pointer', fontWeight: '700',
                  fontSize: '14px', textDecoration: 'none', textAlign: 'center',
                  transition: 'all 0.3s ease', boxShadow: '0 4px 12px rgba(236, 72, 153, 0.3)'
                }}
                onMouseEnter={(e) => (e.currentTarget.style.transform = 'translateY(-2px)', e.currentTarget.style.boxShadow = '0 6px 16px rgba(236, 72, 153, 0.4)')}
                onMouseLeave={(e) => (e.currentTarget.style.transform = 'translateY(0)', e.currentTarget.style.boxShadow = '0 4px 12px rgba(236, 72, 153, 0.3)')}
              >
                📞 Call Now
              </a>
              <a
                href={`https://wa.me/91${product.contact.replace(/\D/g, '')}`}
                target="_blank"
                rel="noopener noreferrer"
                style={{
                  background: '#25D366', color: 'white', border: 'none',
                  padding: '12px 20px', borderRadius: '8px', cursor: 'pointer',
                  fontWeight: '700', fontSize: '14px', textDecoration: 'none',
                  textAlign: 'center', transition: 'all 0.3s ease',
                  boxShadow: '0 4px 12px rgba(37, 211, 102, 0.3)'
                }}
                onMouseEnter={(e) => (e.currentTarget.style.transform = 'translateY(-2px)', e.currentTarget.style.boxShadow = '0 6px 16px rgba(37, 211, 102, 0.4)')}
                onMouseLeave={(e) => (e.currentTarget.style.transform = 'translateY(0)', e.currentTarget.style.boxShadow = '0 4px 12px rgba(37, 211, 102, 0.3)')}
              >
                💬 WhatsApp
              </a>
            </div>
          </div>

          {/* ✅ BUY NOW SECTION */}
          <div
            style={{
              background: buySuccess
                ? 'linear-gradient(135deg, #d1fae5, #a7f3d0)'
                : 'linear-gradient(135deg, #fff7ed, #fef3c7)',
              padding: '20px',
              borderRadius: '12px',
              marginBottom: '24px',
              border: `2px solid ${buySuccess ? '#10b981' : '#f59e0b'}`,
              textAlign: 'center'
            }}
          >
            {buySuccess ? (
              <div>
                <div style={{ fontSize: '40px', marginBottom: '8px' }}>🎉</div>
                <p style={{ fontWeight: '700', color: '#065f46', fontSize: '16px', margin: 0 }}>
                  Order Placed! Seller will contact you soon.
                </p>
              </div>
            ) : (
              <>
                {currentUser && (
                  <div style={{
                    marginBottom: '12px', display: 'flex',
                    justifyContent: 'space-between', alignItems: 'center'
                  }}>
                    <span style={{ fontSize: '13px', color: '#64748b' }}>
                      👤 Logged in as <strong>{currentUser.name}</strong>
                    </span>
                    <button
                      onClick={handleLogout}
                      style={{
                        background: 'none', border: '1px solid #cbd5e1',
                        padding: '4px 10px', borderRadius: '6px',
                        fontSize: '12px', cursor: 'pointer', color: '#64748b'
                      }}
                    >
                      Logout
                    </button>
                  </div>
                )}
                <button
                  onClick={handleBuy}
                  style={{
                    width: '100%', padding: '16px',
                    background: 'linear-gradient(135deg, #f59e0b, #ef4444)',
                    color: 'white', border: 'none', borderRadius: '10px',
                    fontSize: '18px', fontWeight: '800', cursor: 'pointer',
                    boxShadow: '0 6px 20px rgba(245,158,11,0.4)',
                    transition: 'all 0.3s ease', letterSpacing: '0.5px'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.transform = 'translateY(-3px)';
                    e.currentTarget.style.boxShadow = '0 10px 28px rgba(245,158,11,0.5)';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.transform = 'translateY(0)';
                    e.currentTarget.style.boxShadow = '0 6px 20px rgba(245,158,11,0.4)';
                  }}
                >
                  🛒 Buy Now — ${product.price}
                </button>
                {!currentUser && (
                  <p style={{ fontSize: '12px', color: '#92400e', margin: '8px 0 0' }}>
                    🔐 You'll be asked to login / create account
                  </p>
                )}
              </>
            )}
          </div>

        </div>
      </section>

      {/* Related Products */}
      {relatedProducts.length > 0 && (
        <section style={{ marginTop: '60px', paddingTop: '40px', borderTop: '2px solid #e2e8f0' }}>
          <h2 style={{ fontSize: '28px', fontWeight: '800', color: '#0f172a', marginBottom: '24px' }}>
            Similar Products
          </h2>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))',
              gap: '20px'
            }}
          >
            {relatedProducts.map((relatedProduct) => (
              <Link
                key={relatedProduct.id}
                to={`/product/${relatedProduct.id}`}
                style={{ textDecoration: 'none' }}
              >
                <article
                  style={{
                    background: 'white', borderRadius: '12px', overflow: 'hidden',
                    boxShadow: '0 4px 12px rgba(15, 23, 42, 0.08)',
                    transition: 'all 0.3s ease', cursor: 'pointer'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.boxShadow = '0 12px 24px rgba(15, 23, 42, 0.15)';
                    e.currentTarget.style.transform = 'translateY(-4px)';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.boxShadow = '0 4px 12px rgba(15, 23, 42, 0.08)';
                    e.currentTarget.style.transform = 'translateY(0)';
                  }}
                >
                  <div
                    style={{
                      backgroundImage: `url(${relatedProduct.image})`,
                      backgroundSize: 'cover',
                      backgroundPosition: 'center',
                      height: '160px', width: '100%'
                    }}
                  />
                  <div style={{ padding: '16px' }}>
                    <h3 style={{ fontSize: '14px', fontWeight: '700', color: '#0f172a', marginBottom: '8px' }}>
                      {relatedProduct.title}
                    </h3>
                    <p style={{ fontSize: '16px', fontWeight: '800', color: '#ec4899' }}>
                      ${relatedProduct.price}
                    </p>
                  </div>
                </article>
              </Link>
            ))}
          </div>
        </section>
      )}
    </main>
  );
};

export default ProductDetails;
